import { requireAdmin } from '@/lib/auth'; import { adminClient } from '@/lib/supabase'; import { AdminShell } from '@/components/AdminShell';
export default async function Admin(){await requireAdmin(); const s=adminClient(); const [{count:total},{count:downloads}]=await Promise.all([s.from('participants').select('*',{count:'exact',head:true}),s.from('downloads').select('*',{count:'exact',head:true}).eq('status','success')]); const cards=[['Total Participants',total??0],['Certificates Downloaded',downloads??0],['Pending Downloads',Math.max((total??0)-(downloads??0),0)]]; return <AdminShell><h1 className="text-4xl font-black">Dashboard</h1><div className="mt-8 grid gap-6 md:grid-cols-3">{cards.map(c=><div key={c[0]} className="glass rounded-3xl p-6 shadow"><p className="text-slate-500">{c[0]}</p><b className="mt-3 block text-4xl">{c[1]}</b></div>)}</div></AdminShell>}
